function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 2 || grid.length > 1000) return 'grid needs 2 to 1000 rows.';
  const cols = grid[0].length;
  if (cols < 2 || cols > 1000) return 'grid needs 2 to 1000 columns.';
  if (grid.length * cols > 100000) return 'grid has at most 10^5 cells.';
  if (grid.some(row => row.length !== cols)) return 'Every row must have the same length.';
  if (grid.some(row => row.some(v => !Number.isInteger(v) || v < 1 || v > 100000))) return 'Each cell is an integer from 1 to 10^5.';
  return null;
}

