function maxScore(grid) {
  const rows = grid.length;
  const cols = grid[0].length;
  const dp = Array.from({ length: rows }, () => new Array(cols).fill(Infinity));
  let answer = -Infinity;

  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      let before = Infinity;
      if (i > 0) {
        before = Math.min(before, dp[i - 1][j]);
      }
      if (j > 0) {
        before = Math.min(before, dp[i][j - 1]);
      }
      answer = Math.max(answer, grid[i][j] - before);
      dp[i][j] = Math.min(before, grid[i][j]);
    }
  }
  return answer;
}

