function maxScore(grid) {
  // Path DP without the telescoping trick: from each cell, try every single move,
  // then optionally continue with the best path from the landing cell.
  const m = grid.length, n = grid[0].length;
  const from = Array.from({ length: m }, () => new Array(n).fill(null));
  let result = null;
  for (let i = m - 1; i >= 0; i--) {
    for (let j = n - 1; j >= 0; j--) {
      let bestHere = null;
      const targets = [];
      for (let x = i + 1; x < m; x++) targets.push([x, j]);
      for (let y = j + 1; y < n; y++) targets.push([i, y]);
      for (const [x, y] of targets) {
        const gain = grid[x][y] - grid[i][j] + Math.max(0, from[x][y] === null ? 0 : from[x][y]);
        if (bestHere === null || gain > bestHere) bestHere = gain;
      }
      from[i][j] = bestHere;
      if (bestHere !== null && (result === null || bestHere > result)) result = bestHere;
    }
  }
  return result;
}

