function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const rows = size === 'large' ? pick(40, 100) : pick(2, 4);
  const cols = size === 'large' ? pick(40, 100) : pick(2, 4);
  const top = size === 'large' || rand() < 0.2 ? 100000 : pick(1, 12);
  const mode = rand();
  const grid = [];
  for (let i = 0; i < rows; i++) {
    const row = [];
    for (let j = 0; j < cols; j++) {
      if (mode < 0.25) {
        // Values shrink to the right and downward, so every move loses points.
        const base = top - (i * cols + j) * Math.max(1, Math.floor(top / (rows * cols + 1)));
        row.push(Math.max(1, base - pick(0, 1)));
      } else {
        row.push(pick(1, top));
      }
    }
    grid.push(row);
  }
  return [grid];
}
